#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Convert the markdown text to HTML using a markdown library
    // (e.g., libcppmarkdown)
    std::string html;
    std::stringstream ss(markdown);
    ss >> html;
    return html;
}

int main() {
    std::string markdown = "# Hello World\n\nThis is a test.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

